import { Component } from "react";
import "./Header.css";

export default class Header extends Component{
    render(){
    return(
    <div>
        <nav>
        <ul>
            <li><h1 className="logo">TaiLink</h1></li>
            <li><div className="AboutUs"><a href="#">About Us</a></div></li>
        </ul>

        <ul>
            <li></li>
        </ul>
        </nav>
        <div className="orange-navbar">
            <div className="navcontainer">
                <li><a href="#" className="orange-text">Help animals</a></li>
                <li><a href="#" className="orange-text">Post lost animals</a></li>
                <li><a href="#" className="orange-text">Buy a microchip</a></li>
            </div>
        </div>
    </div>
);
}
}
